const languageNames = { es: "Idioma", fr: "Langue", en: "Language", de: "Sprache" };

function switcher(locale, page) {
  const hrefs = {
    es: `../${page}`,
    fr: locale === "fr" ? page : `../fr/${page}`,
    en: locale === "en" ? page : `../en/${page}`,
    de: locale === "de" ? page : `../de/${page}`
  };

  const links = ["es", "fr", "en", "de"]
    .filter((code) => code !== locale)
    .map((code) => `          <a hreflang="${code}" lang="${code}" href="${hrefs[code]}">${code.toUpperCase()}</a>`);

  return [
    `        <div class="language-switcher" aria-label="${languageNames[locale]}">`,
    ...links,
    "        </div>"
  ].join("\n");
}

function translate(html, locale) {
  const column = localeColumn[locale];
  const sortedEntries = [...entries].sort((a, b) => b[0].length - a[0].length);
  const tokens = [];

  sortedEntries.forEach((entry, index) => {
    const token = `__RSE_I18N_${index}__`;
    if (html.includes(entry[0])) {
      html = html.split(entry[0]).join(token);
      tokens.push([token, entry[column]]);
    }
  });

  tokens.forEach(([token, value]) => {
    html = html.split(token).join(value);
  });

  return html;
}

for (const locale of locales) {
  await mkdir(join(root, locale), { recursive: true });

  for (const page of pages) {
    let html = await readFile(join(root, page), "utf8");
    html = html.replace('<html lang="es">', `<html lang="${locale}">`);
    html = html.replace(/        <div class="language-switcher"[\s\S]*?        <\/div>/, switcher(locale, page));
    html = translate(html, locale);
    html = html.replaceAll('href="assets/', 'href="../assets/');
    html = html.replaceAll('src="assets/', 'src="../assets/');
    await writeFile(join(root, locale, page), html, "utf8");
  }
}

console.log(`Generated ${pages.length * locales.length} translated pages.`);
